function save_quote(int $requestId,array $input): int {
    $request=one('SELECT * FROM shop_requests WHERE id=?',[$requestId]);if(!$request || in_array($request['status'],['cancelled','declined'],true))throw new RuntimeException('Diese Anfrage kann nicht angeboten werden.');
    $p=one('SELECT * FROM shop_products WHERE slug=?',[$request['product_slug']]);if(!$p)throw new RuntimeException('Das Produkt der Anfrage wurde nicht gefunden.');
    $id=(int)($input['quote_id']??0);$old=$id?one('SELECT * FROM shop_quotes WHERE id=? AND request_id=?',[$id,$requestId]):null;if($id && (!$old || $old['status']!=='draft'))throw new RuntimeException('Veröffentlichte Angebote bleiben unverändert. Bitte ein neues Angebot erstellen.');
    $title=trim((string)($input['title']??$request['product_name']));if(!$title || strlen($title)>120)throw new RuntimeException('Bitte einen Angebotsnamen mit höchstens 120 Zeichen eintragen.');
    $net=parse_net_price((string)($input['net_price']??''),false);if($net<1)throw new RuntimeException('Bitte einen positiven Nettopreis für das Angebot eintragen.');$tax=vat_from_net($net);
    $billing=(string)($input['billing']??'once');if(!in_array($billing,['once','month','quarter','halfyear','year'],true))throw new RuntimeException('Bitte einen Abrechnungszeitraum auswählen.');
    $date=(string)($input['expires']??'');$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$dt || $dt->format('Y-m-d')!==$date || $dt->setTime(23,59,59)->getTimestamp()<=time() || $dt->getTimestamp()>time()+366*86400)throw new RuntimeException('Bitte ein zukünftiges Gültigkeitsdatum innerhalb eines Jahres eintragen.');$expires=gmdate('Y-m-d H:i:s',$dt->setTime(23,59,59)->getTimestamp());
    if(isset($input['automatic']) && (json_decode($request['configuration'],true)['domain_intent']??'')==='transfer')throw new RuntimeException('Domainumzüge werden persönlich bereitgestellt. Bitte die automatische Neuregistrierung für dieses Angebot deaktivieren.');
    $provider=isset($input['automatic'])?package_provider($p['category']):'manual';$settings=(array)($input['automation'][$provider]??[]);$settings['contract_text']=trim((string)($input['contract_text']??''));if(isset($input['ovh_purchase_ack']))$settings['ovh_purchase_ack']='1';
    $virtual=$p;$virtual['category']=$provider==='manual'?'managed':$p['category'];$virtual['price_cents']=$tax['gross_cents'];$virtual['billing']=$billing;$profile=validated_automation($virtual,$provider,$settings,false);
    $requestedModules=json_decode($request['configuration'],true)['module_configuration']['lines']??[];if($requestedModules){$profile['module_selection']=$requestedModules;if(!str_contains($profile['contract_text'],module_description($requestedModules)))$profile['contract_text'].="\n\nGewählte Zusatzmodule:\n".module_description($requestedModules);}
    $oldPolicy=$old?json_decode($old['profile'],true)['contract_policy']??[]:product_contract_policy($p);$profile['contract_policy']=validated_contract_policy($input,$billing,$oldPolicy);
    if($provider==='ovh')$profile['ovh_purchase_ack']=isset($input['ovh_purchase_ack']);$profile['connection_id']=$provider==='manual' || integration_row($provider)?integration_identity($provider):'';
    $delivery=trim((string)($input['provisioning_notice']??''))?:commerce_settings()['notice_quote'];$dns=trim((string)($input['dns_notice']??''))?:commerce_settings()['notice_dns'];if(strlen($delivery)>3000 || strlen($dns)>3000)throw new RuntimeException('Ein Kundenhinweis ist zu lang.');
    $args=[$title,$net,$tax['gross_cents'],$billing,$provider,json_encode($profile),$delivery,$dns,$expires];
    if($old)query("UPDATE shop_quotes SET title=?,net_cents=?,gross_cents=?,billing=?,provider=?,profile=?,provisioning_notice=?,dns_notice=?,expires_at=? WHERE id=? AND status='draft'",[...$args,$id]);
    else{query('INSERT INTO shop_quotes (title,net_cents,gross_cents,billing,provider,profile,provisioning_notice,dns_notice,expires_at,request_id,customer_id,product_id,domain) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',[...$args,$requestId,$request['customer_id'],$p['id'],$request['domain']]);$id=(int)db()->lastInsertId();}
    audit_event('quote.save',(string)$id);return $id;
}
function quote_product(array $q): array {
    $p=one('SELECT * FROM shop_products WHERE id=?',[$q['product_id']]);if(!$p)throw new RuntimeException('Das Angebotsprodukt wurde entfernt.');$profile=json_decode($q['profile'],true);
    $p['description']=$profile['product_description']??$p['description'];$p['features']=$profile['product_features']??$p['features'];$p['name']=$q['title'];$p['price_cents']=(int)$q['gross_cents'];$p['billing']=$q['billing'];$p['active']=1;$p['_quote_id']=(int)$q['id'];$p['_contract_policy']=$profile['contract_policy']??validated_contract_policy([],$q['billing']);$p['_automation']=['provider'=>$q['provider'],'enabled'=>1,'settings'=>$profile];$p['_options']=['sale_mode'=>'direct','net_cents'=>(int)$q['net_cents'],'tax_bps'=>(int)$q['tax_bps'],'provisioning_notice'=>$q['provisioning_notice'],'dns_notice'=>$q['dns_notice']];
    $p['_module_selection']=$profile['module_selection']??[];if(isset($profile['document_versions']))$p['_document_versions']=$profile['document_versions'];
    if(isset($profile['terms_url']))$p['_documents']=['terms_url'=>$profile['terms_url'],'withdrawal_url'=>$profile['withdrawal_url']];return $p;
}
function publish_quote(int $id): void {
    $q=one("SELECT * FROM shop_quotes WHERE id=? AND status='draft'",[$id]);if(!$q || strtotime($q['expires_at'].' UTC')<=time())throw new RuntimeException('Dieses Angebot ist nicht als gültiger Entwurf verfügbar.');
    $p=quote_product($q);$blockers=package_blockers($p);if($blockers)throw new RuntimeException('Vor dem Versand fehlen: '.implode(', ',array_column(array_values($blockers),0)).'.');
    if(one("SELECT id FROM shop_quotes WHERE request_id=? AND order_id IS NOT NULL AND status IN ('sent','accepted')",[$q['request_id']]))throw new RuntimeException('Zu dieser Anfrage besteht bereits eine Bestellung. Bitte zuerst den Zahlungsstatus prüfen.');
    $profile=json_decode($q['profile'],true);if($q['provider']==='ovh' && empty($profile['ovh_purchase_ack']))throw new RuntimeException('Bitte die kostenpflichtige OVH-Bestellung für dieses Angebot bestätigen.');if(!$profile['contract_text'])throw new RuntimeException('Bitte Leistungs- und Vertragsangaben ergänzen.');$profile['product_description']=$p['description'];$profile['product_features']=$p['features'];$profile+=checkout_documents();$profile['document_versions']=document_versions_for_product($p);$profile['paypal_connection_id']=integration_identity('paypal');
    $customer=one('SELECT * FROM customers WHERE id=?',[$q['customer_id']]);$url=quote_link($id);
    db()->beginTransaction();try{
        $lock=db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':'';one('SELECT id FROM shop_requests WHERE id=?'.$lock,[$q['request_id']]);if(one("SELECT id FROM shop_quotes WHERE request_id=? AND order_id IS NOT NULL AND status IN ('sent','accepted')",[$q['request_id']]))throw new RuntimeException('Zu dieser Anfrage besteht bereits eine Bestellung.');
        $changed=query("UPDATE shop_quotes SET status='sent',published_at=CURRENT_TIMESTAMP,profile=? WHERE id=? AND status='draft'",[json_encode($profile),$id]);if($changed->rowCount()!==1)throw new RuntimeException('Das Angebot wurde bereits bearbeitet.');
        query("UPDATE shop_quotes SET status='cancelled' WHERE request_id=? AND id<>? AND status='sent' AND order_id IS NULL",[$q['request_id'],$id]);query("UPDATE shop_requests SET status='quoted',updated_at=CURRENT_TIMESTAMP WHERE id=?",[$q['request_id']]);
        customer_notification((int)$customer['id'],'quote:'.$id,'Dein Angebot ist da',$q['title'].' · '.money($q['gross_cents']).' inkl. 19 % MwSt.',$url);
        queue_shop_mail('quote:'.$id,$customer['email'],'Dein Angebot – '.$q['title'],"Hallo ".$customer['first_name'].",\n\ndein individuelles Angebot ist jetzt verfügbar.\n\n".$q['title']."\nNettopreis: ".money($q['net_cents'])."\n19 % MwSt.: ".money($q['gross_cents']-$q['net_cents'])."\nGesamt: ".money($q['gross_cents']).' / '.cycle($q['billing'])."\nGültig bis: ".date_de($q['expires_at'])."\n\n".$profile['contract_text']."\n".$q['provisioning_notice']."\n\nAngebot prüfen und mit PayPal bezahlen:\n".Config::FRONTPANEL_SITE_URL.$url."\n\nBitte melde dich mit deinem Kundenkonto an.");db()->commit();
    }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}audit_event('quote.published',(string)$id);
}
function quote_checkout_product(int $id,int $customer): array {
    $q=one("SELECT * FROM shop_quotes WHERE id=? AND customer_id=? AND status='sent'",[$id,$customer]);if(!$q || strtotime($q['expires_at'].' UTC')<=time())throw new RuntimeException('Dieses Angebot ist abgelaufen oder für dein Kundenkonto nicht verfügbar.');
    $request=one('SELECT status FROM shop_requests WHERE id=?',[$q['request_id']]);if(!$request || in_array($request['status'],['cancelled','declined'],true))throw new RuntimeException('Die Anfrage zu diesem Angebot ist nicht mehr aktiv.');$p=quote_product($q);$profile=$p['_automation']['settings'];if(!hash_equals($profile['paypal_connection_id']??'',integration_identity('paypal')))throw new RuntimeException('Die Zahlungsanbindung dieses Angebots muss erneut durch den Shop bestätigt werden.');return $p;
}
function checkout_selection(string $slug,int $customer,int $quote=0,string $domain=''): ?array {if($quote)return quote_checkout_product($quote,$customer);$p=product($slug);return $p && $p['category']==='domain' && $domain!==''?domain_select_product($p,$domain):$p;}
function checkout_documents_for(array $p): array {return $p['_documents']??checkout_documents();}
function parse_net_price(string $input,bool $optional=true): ?int {
    $v=str_replace(',','.',trim($input));if($v==='' && $optional)return null;if(!preg_match('/^\d{1,6}(?:\.\d{1,2})?$/D',$v))throw new RuntimeException('Bitte einen Nettopreis mit höchstens zwei Nachkommastellen eintragen.');[$whole,$fraction]=array_pad(explode('.',$v),2,'');return (int)$whole*100+(int)str_pad($fraction,2,'0');
}
